:root body.night-mode #hero { position: fixed !important; inset: 0 !important; background: #05070c !important; background-image: none !important; }
:root body.night-mode #hero > *:not(.hero-bottom) { display: none !important; }
:root body.night-mode .dashboard > *:not(#hero) { display: none !important; }
:root body.night-mode .hero-bottom { position: fixed !important; inset: 0 !important; display: flex !important; align-items: center !important; justify-content: center !important; height: auto !important; }
:root body.night-mode .hero-bottom > *:not(.hero-clock) { display: none !important; }
:root body.night-mode .hero-clock { background: transparent !important; border: 0 !important; box-shadow: none !important; min-height: 0 !important; height: auto !important; width: auto !important; flex: none !important; padding: 0 !important; animation: nightIn .6s ease-out both; }
:root body.night-mode .hero-clock .clock { font-size: clamp(120px, 26vw, 260px) !important; font-weight: 200 !important; color: rgba(200, 210, 225, .78) !important; text-shadow: 0 0 40px rgba(200, 210, 225, .25); line-height: 1 !important; font-variant-numeric: tabular-nums; }
:root body.night-mode .toast, :root body.night-mode .car-anim { display: none !important; }
@keyframes nightIn { from { opacity: 0; transform: scale(.92); } to { opacity: 1; transform: scale(1); } }
.night-hint { position: fixed; bottom: 12%; left: 50%; transform: translateX(-50%) translateY(8px); z-index: 101; padding: 9px 20px; border-radius: 999px; background: rgba(255, 255, 255, .06); border: 1px solid rgba(255, 255, 255, .1); color: rgba(220, 225, 235, .6); font-size: 13px; letter-spacing: .04em; white-space: nowrap; pointer-events: none; opacity: 0; display: none; }
:root body.night-mode .night-hint { display: block; }
.night-hint.show { animation: nightHint 6s ease forwards; }
@keyframes nightHint { 0% { opacity: 0; transform: translateX(-50%) translateY(8px); } 12% { opacity: 1; transform: translateX(-50%) translateY(0); } 80% { opacity: 1; transform: translateX(-50%) translateY(0); } 100% { opacity: 0; transform: translateX(-50%) translateY(-8px); } }

/* Speed gauge moved to the navigation card: bottom right corner of the card. */
