/* Player: the time labels and the volume row are shown; the customization switches them off (custom.js). */

/* Clock, weather and player: smaller, and see-through so the wallpaper shows behind them. */
.hero-clock, .weather-widget, .player-widget { height: 140px !important; min-height: 140px !important; }
.hero-clock { flex: 0 0 210px !important; width: 210px !important; min-height: 140px; padding: 16px 20px !important; }
