/* Navigation mode: the map is the background, the clock, weather and player sit on it, the climate row is hidden. */
body.player-expanded.nav-mode { background: linear-gradient(160deg, #0d1620, #05080c); }
body.nav-mode .actions-section > :not(#player-stage) { display: none !important; }
