body.radar-only #nav-strip .ns-turnbox, body.radar-only #nav-strip .ns-road, body.radar-only #nav-strip .ns-speed, body.radar-only #nav-strip .ns-home { display: none; }
body.radar-only #nav-strip { top: 18px; height: 52px; left: 50%; right: auto; transform: translateX(-50%); width: auto; min-width: 360px; }

/* In the expanded player the blue line sits inside the frame; the start and end timeline is hidden so it does not show under the card. */
/* Expanded player: the timeline with the minutes and seconds replaces the thin progress bar. */
body.player-expanded .player-widget .track-progress.has-data { display: none !important; }
