/* Navigation card buttons (classic home): start the navigator or send the screen to the instrument panel. */
.hw-nav { position: relative; }
.hw-nav-actions { position: absolute; top: 30px; left: 50%; transform: translateX(-50%); display: flex; justify-content: center; z-index: 5; pointer-events: auto; }
.hw-nav-btn { border: 1px solid var(--line); background: var(--surface-soft); color: var(--text); border-radius: 12px; padding: 4px 12px; font-size: 15px; white-space: nowrap; }

/* Подробное окно состояния автомобиля (hero-widgets.js) */
