/* Иконки кнопок музыки (config.js, APP_ICONS) */
.ui-ico { width: 1em; height: 1em; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; vertical-align: middle; }
.ui-ico.ui-fill { fill: currentColor; stroke: none; }.player-controls .ui-ico { width: 26px; height: 26px; }.player-controls .play .ui-ico { width: 36px; height: 36px; }






/* Variant C: the open player fills the screen. A blurred cover is the background, the cover is large, the controls are big,
