.cv-resize { display: none; position: absolute; right: 9px; bottom: 9px; width: 26px; height: 26px; border-right: 3px solid #ffd84a; border-bottom: 3px solid #ffd84a; border-radius: 0 0 9px 0; cursor: nwse-resize; z-index: 4; touch-action: none; }
body.cover-edit .cv-resize { display: block; }
body.cover-edit.player-expanded:not(.nav-mode) .hero-bottom.in-stage > .hero-clock, body.cover-edit.player-expanded:not(.nav-mode) .hero-bottom.in-stage > #weather-widget, body.cover-edit.player-expanded:not(.nav-mode) .player-widget.expanded { position: relative !important; outline: 2px dashed #ffd84a; outline-offset: 4px; }
body.cover-edit.player-expanded:not(.nav-mode) .player-widget.expanded .player-controls { touch-action: none; }
body.cover-edit.player-expanded:not(.nav-mode) .player-widget.expanded .player-controls button { cursor: grab; touch-action: none; }
body.cover-edit.player-expanded:not(.nav-mode) .player-widget.expanded .player-controls button.cv-dragging { outline: 2px solid #ffd84a; outline-offset: 4px; border-radius: 50%; }

/* Журнал поездок (trips.js): кнопка в окне состояния автомобиля и отдельный экран. */
#trips-open { height: 40px; padding: 0 16px; margin-right: 10px; border-radius: 20px; border: 1px solid var(--accent); background: transparent; color: var(--accent); font-size: 15px; font-weight: 700; letter-spacing: 0; text-transform: none; cursor: pointer; }
#trip-sheet { display: none; position: fixed; inset: 0; z-index: 51; }
body.trip-sheet-open #trip-sheet { display: block; }
.ts-backdrop { position: absolute; inset: 0; background: #000a; }
.ts-panel { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: min(1040px, calc(100vw - 32px)); height: min(600px, calc(100vh - 40px)); display: flex; flex-direction: column; border-radius: 22px; background: var(--bg); border: 1px solid var(--line); color: var(--text); overflow: hidden; }
.ts-head { display: flex; justify-content: space-between; align-items: center; padding: 14px 18px 10px 22px; font-size: 15px; letter-spacing: .14em; text-transform: uppercase; }
.ts-close { width: 40px; height: 40px; border-radius: 50%; border: 1px solid currentColor; background: transparent; color: inherit; font-size: 22px; line-height: 1; cursor: pointer; }
.ts-body { flex: 1; min-height: 0; display: grid; grid-template-columns: 290px 1fr; }
.ts-list { border-right: 1px solid var(--line); overflow-y: auto; padding: 8px 12px 12px; }
.ts-day { color: var(--muted); font-size: 12px; letter-spacing: .08em; text-transform: uppercase; margin: 12px 6px 6px; }
.ts-trip { display: block; width: 100%; text-align: left; background: var(--surface-soft); border: 1px solid var(--line); border-radius: 14px; padding: 11px 13px; margin-bottom: 9px; color: var(--text); cursor: pointer; }
.ts-trip.sel { border-color: var(--accent); }
.ts-trip b { font-size: 16px; font-weight: 700; }
.ts-trip span { display: block; color: var(--muted); font-size: 13px; margin-top: 3px; }
.ts-empty { color: var(--muted); font-size: 15px; padding: 18px 8px; }
.ts-detail { overflow-y: auto; padding: 14px 18px 16px; display: flex; flex-direction: column; gap: 14px; min-width: 0; }
.ts-tiles { display: grid; grid-template-columns: repeat(5, 1fr); gap: 10px; }
.ts-tile { background: var(--surface-soft); border: 1px solid var(--line); border-radius: 14px; padding: 9px 11px; min-width: 0; }
