.ts-tile b { font-size: 21px; }
.ts-tile em { font-style: normal; color: var(--muted); font-size: 12px; }
.ts-chart { flex: 1; min-height: 240px; background: var(--surface-soft); border: 1px solid var(--line); border-radius: 16px; padding: 10px 12px; }
.ts-chart svg { width: 100%; height: 100%; display: block; }
.ts-note { color: var(--muted); font-size: 12px; }

/* Свои виджеты (customwidgets.js): размер карточки задаёт customwidgets.js через --cw-h и --cw-w (без container units, их нет в старом WebView). */
.hw-card.hw-custom { display: flex; flex-direction: column; gap: calc(var(--cw-h, 171px) * 2.5 / 100); position: relative; border: 1px solid var(--card-border); border-radius: 33px; background: var(--card-bg); box-shadow: 0 18px 50px rgba(0, 0, 0, .28); padding: 23px 26px; }
.hw-cw-head { font-size: clamp(11px, calc(var(--cw-h, 171px) * 6.5 / 100), 16px); letter-spacing: .12em; text-transform: uppercase; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-align: center; }
.hw-cw-grid { display: flex; flex-wrap: wrap; gap: calc(var(--cw-h, 171px) * 2.5 / 100) calc(var(--cw-w, 340px) * 2.5 / 100); align-content: center; justify-content: center; align-items: center; flex: 1; min-height: 0; overflow-y: auto; }
.hw-cw-tile { flex: 1 1 calc(var(--cw-w, 340px) * 30 / 100); min-width: 0; height: clamp(56px, calc(var(--cw-h, 171px) * 50 / 100), 120px); padding: 6px calc(var(--cw-w, 340px) * 3 / 100); display: flex; flex-direction: column-reverse; align-items: center; justify-content: center; text-align: center; gap: calc(var(--cw-h, 171px) * 4 / 100); border-radius: clamp(14px, calc(var(--cw-h, 171px) * 13 / 100), 26px); border: 0; background: none; color: var(--text); font-weight: 570; cursor: pointer; }
.hw-cw-tile:active { transform: scale(.97); }
.hw-cw-ico { flex: 0 0 auto; width: clamp(22px, calc(var(--cw-h, 171px) * 24 / 100), 48px); height: clamp(22px, calc(var(--cw-h, 171px) * 24 / 100), 48px); border-radius: 30%; display: inline-flex; align-items: center; justify-content: center; color: #79dcff; background: rgba(var(--accent-rgb), .15); }
.hw-cw-ico svg { width: 100%; height: 100%; }
.hw-cw-name { font-size: clamp(16px, calc(var(--cw-h, 171px) * 12 / 100), 22px); font-weight: 570; line-height: 1.16; max-width: 100%; text-align: center; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.hw-cw-val { flex: 1 1 calc(var(--cw-w, 340px) * 28 / 100); min-width: 0; padding: 0; background: none; border: 0; text-align: center; }
.hw-cw-val small { display: block; color: var(--muted); font-size: clamp(10px, calc(var(--cw-h, 171px) * 6 / 100), 13px); letter-spacing: .12em; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hw-cw-val b { font-weight: 600; font-size: clamp(18px, calc(var(--cw-h, 171px) * 30 / 100), 60px); line-height: 1.1; }
.hw-cw-val:only-child { flex-basis: 100%; }
.hw-cw-val:only-child b { font-size: clamp(22px, calc(var(--cw-h, 171px) * 42 / 100), 80px); }
.hw-cw-val em { font-style: normal; color: var(--muted); font-size: clamp(10px, calc(var(--cw-h, 171px) * 6 / 100), 13px); }
.hw-cw-del { display: none; position: absolute; top: 8px; right: 14px; z-index: 5; height: 32px; padding: 0 12px; border-radius: 16px; border: 1px solid #ff8a6b; background: #2a1410; color: #ffb3a3; font-size: 13px; font-weight: 700; cursor: pointer; }
body.hw-edit .hw-cw-del { display: block; }

/* Свои слоты (customslots.js): выбор иконки в редакторе; сами слоты в стиле кнопок климата. */
.cs-icons { display: grid; grid-template-columns: repeat(auto-fill, minmax(64px, 1fr)); gap: 8px; max-height: 200px; overflow-y: auto; padding: 2px; }
.cs-icon { height: 64px; padding: 0 6px; border-radius: 18px; border: 1px solid var(--line); background: var(--card-bg); color: #79dcff; display: grid; place-items: center; font-size: 13px; cursor: pointer; }
.cs-icon svg { width: 30px; height: 30px; }
.cs-icon[data-key=""] { color: var(--text); font-weight: 570; }
.cs-icon.on { border-color: var(--accent); box-shadow: 0 0 0 2px rgba(var(--accent-rgb), .45); }

/* Тема «Стекло» (style-themes.js): размытие карточек за их фоном. Стандартная тема эти правила не получает. */
html.theme-glass .action-slot, html.theme-glass .hero-clock, html.theme-glass #weather-widget, html.theme-glass .player-widget, html.theme-glass .hw-card, html.theme-glass .hw-custom {
  -webkit-backdrop-filter: blur(12px) saturate(125%); backdrop-filter: blur(12px) saturate(125%);
}
html.theme-tesla .action-slot, html.theme-tesla .hero-clock, html.theme-tesla #weather-widget, html.theme-tesla .player-widget, html.theme-tesla .hw-card, html.theme-tesla .hw-custom {
