:root body.cust-wvis-clock-off .hero-clock { display: none !important; }
.weather-widget { border-radius: var(--wr-weather) !important; }
:root body.cust-wbg-weather-clear .weather-widget { background: transparent !important; box-shadow: none !important; }
:root body.cust-wbg-weather-glass .weather-widget { background: rgba(8, 12, 20, .42) !important; backdrop-filter: blur(16px) !important; -webkit-backdrop-filter: blur(16px) !important; }
:root body.cust-wborder-weather-off .weather-widget { border-color: transparent !important; }
:root body.cust-wvis-weather-off .weather-widget { display: none !important; }
.player-widget { border-radius: var(--wr-player) !important; }
:root body.cust-wbg-player-clear .player-widget { background: transparent !important; box-shadow: none !important; }
:root body.cust-wbg-player-glass .player-widget { background: rgba(8, 12, 20, .42) !important; backdrop-filter: blur(16px) !important; -webkit-backdrop-filter: blur(16px) !important; }
:root body.cust-wborder-player-off .player-widget { border-color: transparent !important; }
:root body.cust-wvis-player-off .player-widget { display: none !important; }
.hw-nav { border-radius: var(--wr-nav) !important; }
:root body.cust-wbg-nav-clear .hw-nav { background: transparent !important; box-shadow: none !important; }
:root body.cust-wbg-nav-glass .hw-nav { background: rgba(8, 12, 20, .42) !important; backdrop-filter: blur(16px) !important; -webkit-backdrop-filter: blur(16px) !important; }
:root body.cust-wborder-nav-off .hw-nav { border-color: transparent !important; }
:root body.cust-wvis-nav-off .hw-nav { display: none !important; }
.hw-compass { border-radius: var(--wr-compass) !important; }
:root body.cust-wbg-compass-clear .hw-compass { background: transparent !important; box-shadow: none !important; }
:root body.cust-wbg-compass-glass .hw-compass { background: rgba(8, 12, 20, .42) !important; backdrop-filter: blur(16px) !important; -webkit-backdrop-filter: blur(16px) !important; }
:root body.cust-wborder-compass-off .hw-compass { border-color: transparent !important; }
:root body.cust-wvis-compass-off .hw-compass { display: none !important; }
.hw-state { border-radius: var(--wr-state) !important; }
:root body.cust-wbg-state-clear .hw-state { background: transparent !important; box-shadow: none !important; }
:root body.cust-wbg-state-glass .hw-state { background: rgba(8, 12, 20, .42) !important; backdrop-filter: blur(16px) !important; -webkit-backdrop-filter: blur(16px) !important; }
:root body.cust-wborder-state-off .hw-state { border-color: transparent !important; }
:root body.cust-wvis-state-off .hw-state { display: none !important; }

/* Светлая тема: стекло, цвета карточек, цвет текста и уведомлений читаются на светлом фоне (custom.js) */
:root[data-theme="light"] body.cust-cardBg-glass .hw-card, :root[data-theme="light"] body.cust-cardBg-glass .weather-widget, :root[data-theme="light"] body.cust-cardBg-glass .player-widget { background: rgba(255, 255, 255, .5) !important; }
:root[data-theme="light"] body.cust-cardColor-graphite { --card-bg: rgba(226, 230, 238, .94); --card-bg-base: rgba(226, 230, 238, .94); }
:root[data-theme="light"] body.cust-cardColor-navy { --card-bg: rgba(214, 228, 246, .94); --card-bg-base: rgba(214, 228, 246, .94); }
:root[data-theme="light"] body.cust-cardColor-warm { --card-bg: rgba(246, 236, 220, .94); --card-bg-base: rgba(246, 236, 220, .94); }
:root[data-theme="light"] body.cust-textColor-white .hw-card, :root[data-theme="light"] body.cust-textColor-white .weather-widget, :root[data-theme="light"] body.cust-textColor-white .player-widget,
:root[data-theme="light"] body.cust-textColor-soft .hw-card, :root[data-theme="light"] body.cust-textColor-soft .weather-widget, :root[data-theme="light"] body.cust-textColor-soft .player-widget { color: #13243a !important; }
:root[data-theme="light"] body.cust-noticeBg-glass .toast, :root[data-theme="light"] body.cust-noticeBg-glass #top-notice, :root[data-theme="light"] body.cust-noticeBg-glass #track-toast { background: rgba(255, 255, 255, .7) !important; color: #13243a !important; }

/* Значки слотов: белые; уровни подогрева оранжевые, вентиляции синие; включённые слоты зелёные; на светлой теме чёрные (custom.js) */
.action-icon { color: #fff; }
.action-slot.level-on.warm .action-icon { color: #ff9a4a !important; }
.action-slot.level-on.cool .action-icon { color: #6fd6ff !important; }
.action-slot.state-on .action-icon { color: #7ee08a !important; }
:root[data-theme="light"] .action-icon { color: #111111 !important; }
:root[data-theme="light"] .action-slot.level-on.warm .action-icon { color: #d9631a !important; }
:root[data-theme="light"] .action-slot.level-on.cool .action-icon { color: #1d7fd1 !important; }
:root[data-theme="light"] .action-slot.state-on .action-icon { color: #1f8f4e !important; }

/* Развёрнутый плеер переносит громкость и время на свои строки (громкость сверху, время снизу). */
body.player-expanded .player-widget.expanded { flex-wrap: wrap !important; }
/* Развёрнутый плеер в альбомном стеке: громкость сверху на всю ширину, обложка с названием и кнопками в ряд, время начала и конца внизу. */
body.player-expanded:not(.nav-mode) .player-widget.expanded { flex-wrap: wrap !important; height: auto !important; min-height: 190px; align-content: center; row-gap: 14px !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .player-vol { order: -1 !important; flex: 0 0 100% !important; width: 100% !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .album-art { order: 0 !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .track-info { order: 1 !important; flex: 1 1 0 !important; min-width: 0 !important; width: auto !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .player-controls { order: 2 !important; flex: 0 0 auto !important; width: auto !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .player-timeline { order: 4 !important; flex: 0 0 100% !important; width: 100% !important; display: flex !important; }
/* В развёрнутом плеере часы, погода и плеер одной высоты: часы и погода растягиваются до высоты плеера. */
body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > .hero-clock, body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > #weather-widget { height: auto !important; min-height: 0 !important; align-self: stretch !important; }
/* Кастомизация в настройках: подпись слева, варианты справа в ровный ряд (не лесенкой). */
.set-row:has(> label + div) { display: grid; grid-template-columns: minmax(170px, 240px) 1fr; align-items: center; gap: 8px 18px; padding: 9px 0; border-bottom: 1px solid rgba(255, 255, 255, .06); }
.set-row:has(> label + div) > label { font-size: 15px; line-height: 1.25; }
.set-row:has(> label + div) > div { display: flex; flex-wrap: wrap; gap: 8px; min-width: 0; }
.set-row:has(> label + div) .set-chip { margin-left: 0; min-height: 40px; padding: 0 14px; border-radius: 12px; font-size: 14px; display: inline-flex; align-items: center; }
:root[data-theme="light"] .set-chip { background: rgba(20, 30, 50, .06); border-color: rgba(20, 30, 50, .16); color: #1b2640; }
:root[data-theme="light"] .set-chip.on { background: rgba(47, 111, 209, .16); border-color: #2f6fd1; }
:root[data-theme="light"] .set-row:has(> label + div) { border-bottom-color: rgba(20, 30, 50, .08); }
/* Светлая тема, компактный плеер на ярких обоях: подложка плотнее, название и исполнитель читаются. */
:root[data-theme="light"] .player-widget:not(.expanded) { background: rgba(255, 255, 255, .84) !important; }
:root[data-theme="light"] .player-widget:not(.expanded) .track-title, :root[data-theme="light"] .player-widget:not(.expanded) .eyebrow { color: #1b2640 !important; }
:root[data-theme="light"] .player-widget:not(.expanded) .track-artist { color: #4a5873 !important; }

/* Подогрев везде оранжевый: руль, лобовое, заднее стекло включённые окрашиваются так же, как уровни подогрева сидений. */
.action-slot.heat-slot.state-on { border-color: rgba(255, 154, 74, .46); background: linear-gradient(145deg, rgba(255, 154, 74, .11), var(--surface) 62%); }
.action-slot.heat-slot.state-on .action-icon { color: #ff9a4a !important; }
.action-slot.heat-slot.state-on .single-lamp { background: #ff9a4a; box-shadow: 0 0 11px rgba(255, 154, 74, .8); }
:root[data-theme="light"] .action-slot.heat-slot.state-on { border-color: rgba(217, 99, 26, .5); background: linear-gradient(145deg, rgba(217, 99, 26, .10), var(--surface) 62%); }
:root[data-theme="light"] .action-slot.heat-slot.state-on .action-icon { color: #d9631a !important; }
:root[data-theme="light"] .action-slot.heat-slot.state-on .single-lamp { background: #d9631a; box-shadow: none; }
/* Окна выбора (настройка слота, настройки) поднимаются над полосой климата внизу экрана, чтобы их нижняя часть не закрывалась. */
.sheet-backdrop { padding-bottom: calc(24px + var(--safe-bottom) + 150px); }
.sheet-backdrop .picker-sheet { max-height: min(790px, calc(100vh - 230px)); }
/* Плитки значков слотов нейтральные во всех темах: цветом окрашивается только значок (подогрев оранжевый, вентиляция синяя, включённое зелёное). */
.action-slot .action-icon { background: rgba(255, 255, 255, .08) !important; }
:root[data-theme="light"] .action-slot .action-icon { background: #eef1f6 !important; }
/* Стекло: плеер и погода почти непрозрачные, с сильным размытием, чтобы фон обоев не просвечивал сквозь текст. */
html.theme-glass .player-widget, html.theme-glass #weather-widget { background: rgba(17, 17, 20, .86) !important; -webkit-backdrop-filter: blur(28px) saturate(120%) !important; backdrop-filter: blur(28px) saturate(120%) !important; }
:root[data-theme="light"] html.theme-glass .player-widget, :root[data-theme="light"] html.theme-glass #weather-widget { background: rgba(255, 255, 255, .88) !important; }
/* Компактный плеер: одна синяя полоса прогресса. Таймлайн (время и громкость) и вторая полоса только в развёрнутом плеере. */
.player-widget:not(.expanded) .player-timeline, .player-widget:not(.expanded) .player-extra, .player-widget:not(.expanded) .player-tl-line { display: none !important; }
.player-widget:not(.expanded) .track-progress { display: block !important; margin-top: 12px; }
